/**
 * Object keys, generated by the server and by nothing else.
 *
 * SECURITY.md S1-15 item 2: "Object keys are server-generated:
 * `${artworkId}/${randomUUID()}.${ext}` where `ext` is derived from the sniffed
 * format, not the filename." Item 3 of S1-9 adds that the original's key must
 * not be derivable from the display key, "so knowing one does not address the
 * other".
 *
 * Both are satisfied by giving the original its own UUID rather than a suffix
 * on the derivative's. `${artworkId}/${a}.jpg` and `${artworkId}/${b}.webp` are
 * unrelated given either one; `${artworkId}/${a}-original.jpg` next to
 * `${artworkId}/${a}-display.webp` would not be, and that is the shape this
 * would have taken without S1-9 spelling it out.
 *
 * The artwork id prefix is required from the other direction too:
 * `artworks.attachImage` refuses any path that does not sit under
 * `${artworkId}/`, so that the database row and the storage object agree about
 * which artwork owns the bytes.
 *
 * NOTHING HERE TAKES A FILENAME. There is no parameter to pass one to, which is
 * what makes "the filename never enters a path" checkable by reading the
 * signature rather than by auditing every caller. The attack it forecloses is
 * a key of `../../other-artist/primary.jpg`, or one carrying a null byte or a
 * newline, escaping the intended prefix during normalisation.
 */
import { randomUUID } from "node:crypto";
import { DERIVATIVE_EXTENSION } from "./formats";

export interface ObjectKeys {
  /** Private bucket. Retained, never served. */
  readonly original: string;
  /** Public bucket. What the detail page loads. */
  readonly display: string;
  /** Public bucket. What a catalog card loads. */
  readonly thumbnail: string;
}

/**
 * The shape every key this module writes must match.
 *
 * Stated as a value so the test asserting it can import the same regular
 * expression the code is written against, rather than a copy of it that can
 * drift.
 */
export const OBJECT_KEY_PATTERN =
  /^[0-9a-f-]{36}\/[0-9a-f-]{36}(?:-thumb)?\.(?:jpg|png|webp|heic|avif)$/;

export function generateObjectKeys(artworkId: string, originalExtension: string): ObjectKeys {
  const originalId = randomUUID();
  const derivativeId = randomUUID();

  return {
    original: `${artworkId}/${originalId}.${originalExtension}`,
    display: `${artworkId}/${derivativeId}.${DERIVATIVE_EXTENSION}`,
    // The thumbnail shares the display derivative's UUID because they are the
    // same public object in two sizes; knowing one already implies the other is
    // public, so there is nothing left to protect between them. The original's
    // key is the one that must stay unguessable, and it does.
    thumbnail: `${artworkId}/${derivativeId}-thumb.${DERIVATIVE_EXTENSION}`,
  };
}
